              if (inn === 4) { full++; row.push([x + w / 2, y + h / 2]); o += `<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${w.toFixed(1)}" height="${h.toFixed(1)}" style="fill:#fbbf24;fill-opacity:.5;stroke:currentColor;stroke-opacity:.5;stroke-width:.7"/>`; }
