            b += `<rect x="${x}" y="${y}" width="54" height="36" rx="8" style="fill:${col};fill-opacity:.9"/>` + fdTxM(x + 27, y + 22, it[2], { s: 9.5, w: 800, c: '#0b1220' }) + fdTxM(x + 62, y + 22, it[3], { a: 'start', s: 10, w: 700 });
            o += pvdG(f, [it[0]], b);
