            o += fdRect(70, 218, 300, 56, { rx: 10, fill: 'rgba(148,163,184,.08)', c: '#94a3b8', so: .5, sw: 1.2 }) + fdTxM(220, 240, '흩어짐은 받아들이고', { s: 10.5, w: 800 }) + fdTxM(220, 259, '이동과 이탈은 일찍 알아챈다', { s: 10.5, w: 800, c: fdAc });
