            const bell = 'M' + bx + ' ' + k.Y(-3.6) + ' L' + pts.map((p) => p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join(' L') + ' L' + bx + ' ' + k.Y(3.6) + ' Z';
