            const ch = [['어디', 'ETCH-03', '챔버 B', C.eq], ['무엇', '압력 편차', '알람 정지', RED], ['언제', '14:32', '식각 2단계', C.pr], ['지금', '정지 · 로트', '홀드함', AC], ['요청', '와서 확인', '부탁드림', C.op]];
