            o += pvdG(f ? [f] : null, ['gap'], A.ln(`M${X0 + 10 * CW} 226 H${X0 + 6 * CW}`, AMB, 2, .95, '4 3') + fdArr(X0 + 6 * CW - 1, 226, 'l', AMB) + lab(X0 + 8 * CW, 218, '거슬러 오른다', AMB, 'middle', 9.5));
