            o += A.ln('M420 160 H40', AMB, 1.8, .95, '5 3') + fdArr(37, 160, 'l', AMB) + lab(230, 178, '출력에서 입력 쪽으로 한 단계씩 거슬러 오른다', AMB, 'middle', 10);
