            HB.forEach((h, i) => { const x = 150 + i * 70; o += R(x, 196 - h, 36, h, [RED, ORG, AMB, OKC][i], { fo: .5, c: [RED, ORG, AMB, OKC][i], sw: 1.2, rx: 2 }) + lab(x + 18, 208, NB[i], GR, 'middle', 9); });
            o += A.ln('M140 196 H430', GR, 1, .6);
