            wv += R(x0 + 40, 26, 80, 130, RED, { fo: .06, c: RED, sw: 1, rx: 4, dash: '3 3' }) + lab(x0 + 80, 170, '쉬는 구간: 클록이 멈춘다', RED, 'middle', 9);
            o += pvdG(f ? [f] : null, ['wv'], wv);
