              return pvdG(f ? [f] : null, [id], box(x, 10, 140, 124, GR) + lab(x + 70, 26, nm, col, 'middle', 10) + M(lx, 40, w, 60, ok2 ? OKC : CLK) + M(rx, 40, w, 60, ok2 ? OKC : CLK) + wob + dim(lx + w, rx, 112, '', col) + (ok2 ? ok(x + 70, 118) : bad(x + 70, 118)));
