            o += pvdG(f ? [f] : null, ['cm'], lab(332, 118, '같은 잡음이 들어오면: 지움', RED, 'start', 9) + sine(332, 138, 86, 6, 1.5, RED, 2) + sine(332, 154, 86, 6, 1.5, RED, 2) + A.ln('M332 176 H418', RED, 2.6));
            return dgSvg('차동 쌍: ' + s.label, o, '0 0 440 190');
