            o += A.ln(`M${px} ${py} V${py + ph} H${px + pw}`, GR, 1.2, .8) + lab(px + pw, py + ph + 18, '주파수 (로그)', GR, 'end', 8.5) + lab(px - 4, py + 6, '이득 (dB)', GR, 'end', 8.5);
