            o += pvdG(f ? [f] : null, ['lo'], curve(10, 3.2, OKC) + lab(X(.1), Y(1) - 8, '낮은 이득', OKC, 'start', 9.5) + dot(X(3.2), Y(.7), 4, OKC) + lab(X(3.2), py + ph + 30, '넓은 대역', OKC, 'middle', 8.5));
            return dgSvg('이득과 대역폭: ' + s.label, o, '0 0 440 190');
