            const B = (id, x, nm, sub, col) => pvdG(f ? [f] : null, [id], box(x, 44, 92, 52, col) + lab(x + 46, 66, nm, col, 'middle', 11) + lab(x + 46, 84, sub, GR, 'middle', 9.5));
            o += B('lst', 12, '고장 목록', '선마다 0·1', GR) + A.ln('M104 70 H122', GR, 1.8) + arr(122, 70, 'r', GR);
