      const week = ['월', '화', '수', '목', '금', '토', '일'].map((w, i) => { const d = dateStr(new Date(mon.getFullYear(), mon.getMonth(), mon.getDate() + i)); return `<span class="${attendDays.includes(d) ? 'on' : ''}${d === tk ? ' now' : ''}"><i></i>${w}</span>`; }).join('');
