      const n = e ? e.th.length * 2 + e.q + e.iv : 0, a = n >= 8 ? '70' : n >= 4 ? '48' : '28', ic = e ? `${e.th.length ? '📖' : ''}${e.q ? '✏️' : ''}${e.iv ? '🎤' : ''}` : '';
