        if (k === fjIdx && rail.scrollWidth > rail.clientWidth) rail.scrollTo({ left: b.offsetLeft - (rail.clientWidth - b.offsetWidth) / 2, behavior: 'smooth' });   // 레일만 가로로 움직인다 (scrollIntoView 는 페이지까지 세로로 끌고 가 화면이 튄다)
