      jxLoading = new Promise((ok, no) => { const sc = document.createElement('script'); sc.src = 'jx.js?v=3'; sc.onload = ok; sc.onerror = () => no(new Error('jx.js')); document.head.appendChild(sc); }).catch((e) => { jxLoading = null; throw e; });
