      rail.innerHTML = GD_CH.map((n, i) => `<button type="button" onclick="guideGo(${i})" aria-label="${n}"><i></i><span>${n}</span></button>`).join('');
      host.appendChild(bar); host.appendChild(rail); ctx.extra.push(bar, rail);
